def load_official_catalog(apps, schema_editor):
    Product = apps.get_model("messen", "MachineProduct")
    Variant = apps.get_model("messen", "MachineVariant")
    Area = apps.get_model("messen", "RecyclingArea")
    Material = apps.get_model("messen", "RecyclingMaterial")
    for order, (category, series, description, advantages, groups, versions) in enumerate(DATA):
        product, created = Product.objects.get_or_create(
            model_name=series,
            defaults={"category":category,"headline":description[:240],"description":description,
                      "advantages":advantages.replace("|","\\n"),"position":order+1,"published":True}
        )
        if not created:
            changed = []
            for key, val in (("headline",description[:240]),("description",description),
                             ("advantages",advantages.replace("|","\\n"))):
                if not getattr(product,key):
                    setattr(product,key,val); changed.append(key)
            if changed: product.save(update_fields=changed)
        mats = []
        for group in groups.split(";"):
            if not group: continue
            slug, names = group.split(":",1)
            try: area = Area.objects.get(slug=slug)
            except Area.DoesNotExist: continue
            for name in names.split(","):
                material, _ = Material.objects.get_or_create(area=area,name=name.strip())
                mats.append(material)
        for index,(suffix,version,engine,drive,weight) in enumerate(versions):
            name = series + (" " + suffix if suffix else "")
            variant, new = Variant.objects.get_or_create(
                name=name, defaults={
                    "product":product,"version":version,"engine":engine,"drive":drive,
                    "weight":weight,"operating_principle":description,
                    "position":index+1,"published":True,
                }
            )
            if not new:
                changes=[]
                for key,val in (("version",version),("engine",engine),("drive",drive),
                                ("weight",weight),("operating_principle",description)):
                    if val and not getattr(variant,key):
                        setattr(variant,key,val); changes.append(key)
                if changes: variant.save(update_fields=changes)
            variant.materials.add(*mats)

class Migration(migrations.Migration):
    dependencies = [("messen","0014_recycling_areas_materials")]
    operations = [migrations.RunPython(load_official_catalog, migrations.RunPython.noop)]
